function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
  describe("anim of vector field in cycling resolution, potential colored");
  colorMode(HSB);
}

function draw() {
  blendMode(BLEND);
  background("rgb(0,0,12)");
  // blendMode(DIFFERENCE); // speed killer
  drawField(40 + sin(frameCount / 123) * 30);
}

function drawField(n = 80) {
  translate(width / 2, height / 2);
  rotate(sin(frameCount/321)*PI)
  const st = width / n;
  strokeWeight(2);
  const scl = (1 / max(width, height)) * 4;
  for (let y = -width / 2 + st / 2; y < width / 2; y += st) {
    for (let x = -height / 2 + st / 2; x < height / 2; x += st) {
      point(x, y);
      const ang = 5 * f(x * scl, y * scl);
      push();
      translate(x, y);
      rotate(ang);
      stroke(((((ang + TWO_PI) % TWO_PI) / TWO_PI) * 360 + 180) % 360, 65, 75);
      line(0, 0, st, 0);
      pop();
    }
  }
}

function f(x, y) {
  // https://www.slideserve.com/tan/vector-fields-acting-on-a-curve
  return (x + y) / exp(x * x + y * y);
}
